mapper.delete:
DELETE FROM property_actual_transaction
WHERE source_api = #{sourceApi}
  AND sgg_code = #{sggCode}
  AND source_deal_ym = #{dealYm}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM market_transaction_sync
    WHERE source_api = #{sourceApi}
      AND sgg_code = #{sggCode}
      AND deal_ym = #{dealYm}
      AND last_success_at IS NOT NULL
      AND last_attempt_status = 'SUCCESS'
)

mapper.update:
UPDATE property
SET market_calculated_at =
        CASE
            WHEN market_calculated_at IS NULL
                OR NOT (
                    market_status <=> #{status}
                    AND (
                        #{preserveExistingScore}
                        OR (
                            evaluation_score <=> #{evaluationScore}
                            AND market_reference_price <=> #{referencePrice}
                            AND market_transaction_count <=> #{transactionCount}
                            AND market_basis_level <=> #{basisLevel}
                        )
                    )
                ) THEN NOW()
            ELSE market_calculated_at
        END,
    evaluation_score =
        CASE
            WHEN #{preserveExistingScore} THEN evaluation_score
            ELSE #{evaluationScore}
        END,
    market_reference_price =
        CASE
            WHEN #{preserveExistingScore} THEN market_reference_price
            ELSE #{referencePrice}
        END,
    market_transaction_count =
        CASE
            WHEN #{preserveExistingScore} THEN market_transaction_count
            ELSE #{transactionCount}
        END,
    market_basis_level =
        CASE
            WHEN #{preserveExistingScore} THEN market_basis_level
            ELSE #{basisLevel}
        END,
    market_status = #{status}
WHERE id = #{propertyId}
